#!/usr/bin/env node
// MIT. Native commands use the same original workspace as the local operator UI.
import { readFile, writeFile, mkdir, open } from 'node:fs/promises';
import { resolve, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { randomUUID } from 'node:crypto';
import { openGrantsWorkspace } from './workspace.mjs';
import { grantsAction, startGrantsServer } from './server.mjs';

const HELP = 'Grants.gov opportunity workspace\n\n'+
'node grantsgov/cli.mjs <command> --workspace /private/grants [options]\n\n'+
'  init | status                    Open or inspect the original workspace\n'+
'  serve [--port 0]                  Start the private local operator UI\n'+
'  serve --startup-format managed ...  Start the saved installed Applications selection\n'+
'  action --action NAME --input JSON_FILE\n'+
'                                   Run any documented native workspace action\n'+
'  query --name NAME --keyword WORDS [--statuses posted,forecasted]\n'+
'                                   Save a search (new query revision zero)\n'+
'  capture --query ID [--revision N] [--operation ID]\n'+
'                                   Retain every page and full notice detail\n'+
'  resume --capture ID               Resume the same original acquisition\n'+
'  import --file CAPTURE_JSON        Receive a complete original source capture\n'+
'  receive --file EDITION_JSON       Receive an edition and its qualification\n'+
'  restore --file WORKSPACE_JSON     Receive a research backup into an empty workspace\n'+
'  edition --capture ID --name NAME [--ids ID,ID]\n'+
'  opportunities --edition ID [--search TEXT] [--offset N] [--limit N]\n'+
'  opportunity --edition ID --id ID\n'+
'  review --edition ID --id ID --revision N --file REVIEW_JSON\n'+
'  compare --before ID --after ID\n'+
'  export --kind KIND --out FILE [--edition ID] [--capture ID] [--merchant ID] [--id ID]\n'+
'  download --id EXPORT_SHA --out FILE\n'+
'  merchant --edition ID [--file CONFIG_JSON]\n'+
'  preview --merchant ID [--file QUERY_JSON]\n\n'+
'Use --request ID to replay a mutation with exactly the same input.\n'+
'Use --buyers HOST_BINDINGS_JSON for native customer workspace aliases.\n'+
'Export kinds: workspace, edition, capture, merchant, comparison, workshare-md, workshare-html.\n'+
'Complete API and publishing inputs are documented in README.md.\n';
function args(argv) {
  const values={_:[]};
  for(let i=0;i<argv.length;i++){
    const key=argv[i];
    if(!key.startsWith('--')){values._.push(key);continue;}
    if(key==='--help'){values.help=true;continue;}
    if(i+1>=argv.length||argv[i+1].startsWith('--'))throw Error('A value is required for '+key);
    if(Object.hasOwn(values,key.slice(2)))throw Error('Duplicate option '+key);
    values[key.slice(2)]=argv[++i];
  }
  return values;
}
function required(value,name){if(!value)throw Error('Supply --'+name);return value;}
function number(value,fallback){return value===undefined?fallback:Number(value);}
const readJSON=async path=>JSON.parse(await readFile(resolve(path),'utf8'));
async function outputFile(path,data){
  path=resolve(required(path,'out'));await mkdir(dirname(path),{recursive:true,mode:0o700});
  const handle=await open(path,'wx',0o600);try{await handle.writeFile(data);await handle.sync();}finally{await handle.close();}
  return path;
}
async function download(workspace,id,path){
  const first=await workspace.readExport(id,{offset:0,limit:8*1024*1024});
  const target=resolve(required(path,'out'));await mkdir(dirname(target),{recursive:true,mode:0o700});
  const handle=await open(target,'wx',0o600);let next=0;
  try{
    let part=first;
    while(true){
      await handle.write(Buffer.from(part.data,'base64'),0,part.bytesRead,next);next+=part.bytesRead;
      if(part.nextOffset===null)break;
      part=await workspace.readExport(id,{offset:part.nextOffset,limit:8*1024*1024});
    }
    await handle.sync();
  }finally{await handle.close();}
  return {file:target,bytes:first.file.bytes,sha256:first.file.sha256,exportId:id};
}
export async function main(argv=process.argv.slice(2)){
  const options=args(argv),command=options._[0]??'help';
  if(options.help||command==='help'){process.stdout.write(HELP);return;}
  const directory=resolve(required(options.workspace,'workspace'));
  const buyerWorkspaces=options.buyers?await readJSON(options.buyers):[];
  if(command==='serve'){
    const {prepareGrantsManagedLaunch,grantsManagedStartup}=await import('./launch.mjs');
    if(options['startup-format']!==undefined&&options['startup-format']!=='managed')
      throw Error('Use --startup-format managed with the saved Applications review.');
    const launch=options['startup-format']==='managed'?await prepareGrantsManagedLaunch({
      directory,sourceDirectory:required(options['source-directory'],'source-directory'),
      expectedSourceSha256:required(options['source-sha256'],'source-sha256'),
      expectedWorkspaceIdentity:required(options['workspace-identity'],'workspace-identity'),
      buyersFile:options.buyers?resolve(options.buyers):undefined,
      expectedBuyersSha256:options['buyers-sha256']
    }):null;
    const server=await startGrantsServer({directory,port:number(options.port,0),
      buyerWorkspaces:launch?launch.buyers.buyerWorkspaces:buyerWorkspaces});
    try{
      const ready=launch?await grantsManagedStartup({launch,workspace:server.workspace,service:server}):
        {url:server.url,workspace:directory,pid:process.pid};
      process.stdout.write(JSON.stringify(ready)+'\n');
    }catch(error){await server.close();throw error;}
    let stopping=false;
    const close=()=>{if(stopping)return;stopping=true;void server.close().catch(error=>{
      process.stderr.write(JSON.stringify({error:{code:error.code??'GRANTS_CLOSE_FAILED',message:error.message}})+'\n');
      process.exitCode=1;
    });};
    process.once('SIGINT',close);process.once('SIGTERM',close);
    return server;
  }
  const workspace=await openGrantsWorkspace({directory,buyerWorkspaces});
  const requestId=options.request??'request-'+randomUUID();
  let runningCapture,retainedRelease=false;
  const abort=()=>{if(runningCapture)void workspace.pauseCapture(runningCapture);};
  process.once('SIGINT',abort);process.once('SIGTERM',abort);
  try{
    let result;
    if(command==='init'||command==='status')result=await workspace.snapshot();
    else if(command==='action'){
      const action=required(options.action,'action'),input=options.input?await readJSON(options.input):{};
      result=await grantsAction(workspace,action,input);
      if(action==='publisher.release.start')retainedRelease=true;
      if(action==='capture.start'){runningCapture=result.id;result=await workspace.waitCapture(result.id);}
    }else if(command==='query'){
      const input=options.file?await readJSON(options.file):{
        keyword:options.keyword??'',opportunityNumber:options.number??'',
        statuses:(options.statuses??'posted,forecasted').split(',').filter(Boolean),
        agencies:(options.agencies??'').split(',').filter(Boolean),
        eligibilities:(options.eligibilities??'').split(',').filter(Boolean),
        pageSize:number(options['page-size'],25)
      };
      result=await workspace.querySave({requestId,id:options.id,expectedRevision:number(options.revision,0),
        name:required(options.name,'name'),definition:input});
    }else if(command==='capture'||command==='resume'){
      let input;
      if(command==='resume')input={requestId,captureId:required(options.capture,'capture')};
      else{
        const queryId=required(options.query,'query'),state=await workspace.snapshot();
        const query=state.queries.find(value=>value.id===queryId);
        input={requestId,queryId,expectedRevision:number(options.revision,query?.revision),
          operationId:options.operation??requestId};
      }
      result=await workspace.startCapture(input);runningCapture=result.id;
      result=await workspace.waitCapture(result.id);
      if(!['complete','partial'].includes(result.status))process.exitCode=2;
    }else if(command==='import'||command==='receive'||command==='restore'){
      const packet=await readJSON(required(options.file,'file')),input={requestId,packet,name:options.name??'Received grant research'};
      result=command==='import'?await workspace.importOriginal(input):
        command==='receive'?await workspace.receiveEdition(input):await workspace.restore(input);
    }else if(command==='edition')result=await workspace.createEdition({requestId,captureId:required(options.capture,'capture'),
      name:required(options.name,'name'),opportunityIds:options.ids?.split(',').filter(Boolean),parentId:options.parent});
    else if(command==='opportunities')result=await workspace.rows(required(options.edition,'edition'),{
      search:options.search??'',status:options.status,agency:options.agency,closingFrom:options.from,closingTo:options.to,
      sort:options.sort??'closing_date',direction:options.direction??'asc',offset:number(options.offset,0),limit:number(options.limit,50)});
    else if(command==='opportunity')result=await workspace.opportunity(required(options.edition,'edition'),required(options.id,'id'));
    else if(command==='review')result=await workspace.reviewSave({requestId,editionId:required(options.edition,'edition'),
      opportunityId:required(options.id,'id'),expectedRevision:number(options.revision,0),review:await readJSON(required(options.file,'file'))});
    else if(command==='compare')result=await workspace.compare(required(options.before,'before'),required(options.after,'after'),
      {offset:number(options.offset,0),limit:number(options.limit,250)});
    else if(command==='merchant')result=await workspace.merchant({...(options.file?await readJSON(options.file):{}),requestId,
      editionId:required(options.edition,'edition')});
    else if(command==='preview')result=await workspace.merchantPreview(required(options.merchant,'merchant'),
      options.file?await readJSON(options.file):{limit:5});
    else if(command==='export'){
      const descriptor=await workspace.exportFile({kind:required(options.kind,'kind'),editionId:options.edition,
        captureId:options.capture,merchantId:options.merchant,opportunityId:options.id,before:options.before,after:options.after,
        includeReviews:true});
      result=await download(workspace,descriptor.id,options.out);
    }else if(command==='download')result=await download(workspace,required(options.id,'id'),options.out);
    else throw Error('Unknown command '+command+'. Use --help.');
    process.stdout.write(JSON.stringify(result,null,2)+'\n');
  }finally{
    process.removeListener('SIGINT',abort);process.removeListener('SIGTERM',abort);
    if(retainedRelease){const close=()=>void workspace.close();process.once('SIGINT',close);process.once('SIGTERM',close);}
    else await workspace.close();
  }
}
if(import.meta.url===pathToFileURL(process.argv[1]??'').href)
  main().catch(error=>{process.stderr.write(JSON.stringify({error:{code:error.code??'GRANTS_COMMAND_FAILED',message:error.message}})+'\n');process.exitCode=1;});

// MIT. Managed identity and lifecycle for the original Grants.gov research workspace.
import { constants } from 'node:fs';
import { open, lstat, realpath } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { absolute, privateDirectory, readPrivate, object, digest, identity, fault } from '../postgres/publisher/files.mjs';

export const GRANTS_STARTUP_SCHEMA = 'stellar-forge.grantsgov-workspace-startup.v1';
export const GRANTS_LAUNCH_FILES = Object.freeze([
  'launch.mjs','workspace.mjs','server.mjs','cli.mjs','source.mjs','transport.mjs',
  'capture.mjs','capture-storage.mjs','acquire.mjs','app.mjs','index.html','app.css','browser-assets.json',
]);
const SCHEMA = 'stellar-forge.grantsgov-workspace.v1';
const HASH = /^[a-f0-9]{64}$/;
const WORKSPACE_ID = /^GW-[a-f0-9-]{36}$/;
const SOURCE_DIRECTORY = dirname(fileURLToPath(import.meta.url));
const changed = () => fault('GRANTS_MANAGED_INPUT_CHANGED',
  'Review the current Grants.gov workspace, buyer bindings and installed source before starting.',409);
const inode = value => ({dev:String(value.dev),ino:String(value.ino)});
const sameInode = (a,b) => a.dev===b.dev && a.ino===b.ino;
function expected(value) {
  if(value!==undefined&&!HASH.test(value))throw fault('GRANTS_MANAGED_HASH_REQUIRED');
}

/** Workspace JSON is atomically replaced as work advances. Bind the immutable
 * workspace ID, creation time and original private directory inode, not its
 * mutable revisions, captured pages or qualification records. */
export async function inspectGrantsWorkspace(directory,{expectedIdentity}={}) {
  absolute(directory);expected(expectedIdentity);await privateDirectory(directory);
  const before=await lstat(directory,{bigint:true});
  if(await realpath(directory)!==directory)throw fault('GRANTS_ORIGINAL_DIRECTORY_REQUIRED');
  const bytes=await readPrivate(join(directory,'workspace.json'),32*1024*1024);
  let saved;try{saved=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));}
  catch{throw fault('GRANTS_WORKSPACE_FORMAT_INVALID');}
  const after=await lstat(directory,{bigint:true});
  if(!sameInode(before,after))throw changed();
  if(!object(saved)||saved.schema!==SCHEMA||!WORKSPACE_ID.test(saved.id??'')||
    !Number.isFinite(Date.parse(saved.createdAt))||
    ['queries','captures','editions','reviews','exports','merchants','requests'].some(key=>!object(saved[key])))
    throw fault('GRANTS_WORKSPACE_FORMAT_INVALID','Initialize or reopen the original Grants.gov workspace.');
  const value={schema:'stellar-forge.grantsgov-workspace-identity.v1',directory,
    directoryIdentity:inode(after),workspaceId:saved.id,createdAt:saved.createdAt};
  const sha256=identity(value);
  if(expectedIdentity!==undefined&&sha256!==expectedIdentity)throw changed();
  return {...value,sha256};
}

/** Reads host-selected directory references. Payer keys and policy stay in the
 * original SF88 workspace and are never loaded during application review. */
export async function readGrantsLaunchBuyers(file,{expectedSha256}={}) {
  expected(expectedSha256);
  if(file===undefined||file===null){
    if(expectedSha256!==undefined)throw fault('GRANTS_BUYER_BINDINGS_REQUIRED');
    return {file:null,sha256:null,buyerWorkspaces:[]};
  }
  absolute(file,'buyer bindings file');
  if(await realpath(file)!==file)throw fault('GRANTS_BUYER_BINDINGS_PATH_CHANGED');
  const bytes=await readPrivate(file,1024*1024),sha256=digest(bytes);
  if(expectedSha256!==undefined&&expectedSha256!==sha256)throw changed();
  let parsed;try{parsed=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));}
  catch{throw fault('GRANTS_BUYER_BINDINGS_INVALID');}
  if(!Array.isArray(parsed)||parsed.length>32)throw fault('GRANTS_BUYER_BINDINGS_INVALID');
  const ids=new Set(),directories=new Set(),buyerWorkspaces=[];
  for(const binding of parsed){
    if(!object(binding)||Object.keys(binding).some(key=>!['id','directory'].includes(key))||
      !/^[A-Za-z0-9][A-Za-z0-9_.:-]{0,159}$/.test(binding.id??'')||ids.has(binding.id))
      throw fault('GRANTS_BUYER_BINDINGS_INVALID');
    const directory=absolute(binding.directory,'original buyer workspace');
    await privateDirectory(directory);
    if(await realpath(directory)!==directory||directories.has(directory))
      throw fault('GRANTS_BUYER_BINDINGS_INVALID');
    ids.add(binding.id);directories.add(directory);buyerWorkspaces.push({id:binding.id,directory});
  }
  return {file,sha256,buyerWorkspaces};
}
async function sourceFile(path){
  const handle=await open(path,constants.O_RDONLY|constants.O_NOFOLLOW);
  try{
    const before=await handle.stat();
    if(!before.isFile()||before.size>2*1024*1024)throw fault('GRANTS_MANAGED_SOURCE_INVALID');
    const bytes=await handle.readFile(),after=await handle.stat();
    if(bytes.length!==before.size||before.size!==after.size||before.mtimeMs!==after.mtimeMs||
      before.ctimeMs!==after.ctimeMs)throw changed();
    return {bytes:bytes.length,sha256:digest(bytes)};
  }finally{await handle.close();}
}
export async function inspectGrantsLaunchSource(directory,{expectedSha256}={}){
  absolute(directory,'Grants.gov source directory');expected(expectedSha256);
  if(await realpath(directory)!==directory||!(await lstat(directory)).isDirectory())
    throw fault('GRANTS_MANAGED_SOURCE_INVALID');
  const files=[];for(const name of GRANTS_LAUNCH_FILES)files.push({name,...await sourceFile(join(directory,name))});
  const value={schema:'stellar-forge.grantsgov-launch-source.v1',files},sha256=identity(value);
  if(expectedSha256!==undefined&&sha256!==expectedSha256)throw changed();
  return {...value,directory,sha256};
}
export async function prepareGrantsManagedLaunch({directory,sourceDirectory,
  expectedSourceSha256,expectedWorkspaceIdentity,buyersFile,expectedBuyersSha256}={}){
  absolute(directory);absolute(sourceDirectory);
  if(!HASH.test(expectedSourceSha256??'')||!HASH.test(expectedWorkspaceIdentity??'')||
    Boolean(buyersFile)!==Boolean(expectedBuyersSha256))throw fault('GRANTS_MANAGED_REVIEW_REQUIRED');
  const source=await inspectGrantsLaunchSource(sourceDirectory,{expectedSha256:expectedSourceSha256});
  const executed=await inspectGrantsLaunchSource(SOURCE_DIRECTORY,{expectedSha256:expectedSourceSha256});
  const workspace=await inspectGrantsWorkspace(directory,{expectedIdentity:expectedWorkspaceIdentity});
  const buyers=await readGrantsLaunchBuyers(buyersFile,{expectedSha256:expectedBuyersSha256});
  return {directory,expectedWorkspaceIdentity,source,executed,workspace,buyers};
}
export async function grantsManagedStartup({launch,workspace,service}={}){
  if(!launch||!workspace||!service||launch.directory!==workspace.directory)
    throw fault('GRANTS_MANAGED_REVIEW_REQUIRED');
  const current=await inspectGrantsWorkspace(workspace.directory,{expectedIdentity:launch.expectedWorkspaceIdentity});
  const native=await workspace.snapshot();
  if(native.id!==current.workspaceId||native.createdAt!==current.createdAt)throw changed();
  await inspectGrantsLaunchSource(launch.source.directory,{expectedSha256:launch.source.sha256});
  await inspectGrantsLaunchSource(launch.executed.directory,{expectedSha256:launch.source.sha256});
  await readGrantsLaunchBuyers(launch.buyers.file,{
    expectedSha256:launch.buyers.sha256??undefined});
  return {schema:GRANTS_STARTUP_SCHEMA,status:'GRANTS_WORKSPACE_READY',
    instanceId:service.instanceId,pid:process.pid,directory:workspace.directory,
    workspaceId:current.workspaceId,workspaceIdentity:current.sha256,
    sourceDirectory:launch.source.directory,launchSourceDirectory:launch.executed.directory,
    sourceSha256:launch.source.sha256,sourceFiles:launch.source.files,
    buyersFile:launch.buyers.file,buyersSha256:launch.buyers.sha256,
    buyerWorkspaces:launch.buyers.buyerWorkspaces.map(({id})=>id),
    grantsWorkspace:service.url};
}

// MIT. Authenticated local operator surface for the retained Grants.gov workspace.
import { createServer } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomBytes, randomUUID, timingSafeEqual } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { openGrantsWorkspace } from './workspace.mjs';

const ASSETS = JSON.parse(readFileSync(new URL('./browser-assets.json',import.meta.url),'utf8'));
const STATIC = Object.freeze(Object.fromEntries(ASSETS.routes));
const own = Object.prototype.hasOwnProperty;
const error = (code,message,status=400) => Object.assign(new Error(message),{code,status});
const object = value => value!==null && typeof value==='object' && !Array.isArray(value);
const iso = () => new Date().toISOString();
const jsonBytes = value => Buffer.from(JSON.stringify(value)+'\n');

export async function grantsAction(workspace,action,input={}) {
  if(!object(input))throw error('ACTION_INPUT_REQUIRED','Send an action input object.');
  switch(action) {
    case 'workspace.status':return workspace.snapshot();
    case 'query.save':return workspace.querySave(input);
    case 'capture.start':return workspace.startCapture(input);
    case 'capture.status':return workspace.captureStatus(input.captureId);
    case 'capture.pause':return workspace.pauseCapture(input.captureId);
    case 'capture.wait':return workspace.waitCapture(input.captureId);
    case 'capture.import':return workspace.importOriginal(input);
    case 'edition.create':return workspace.createEdition(input);
    case 'edition.receive':return workspace.receiveEdition(input);
    case 'edition.read':return workspace.edition(input.editionId);
    case 'opportunity.list':return workspace.rows(input.editionId,input);
    case 'opportunity.read':return workspace.opportunity(input.editionId,input.opportunityId);
    case 'review.save':return workspace.reviewSave(input);
    case 'edition.compare':return workspace.compare(input.before,input.after,input);
    case 'workshare.read':return workspace.workshare(input.editionId,input.opportunityId,input);
    case 'merchant.create':return workspace.merchant(input);
    case 'merchant.preview':return workspace.merchantPreview(input.merchantId,input.query??{});
    case 'merchant.read':return workspace.merchantFiles(input.merchantId);
    case 'export.create':return workspace.exportFile(input);
    case 'export.read':return workspace.readExport(input.id,input);
    case 'workspace.restore':return workspace.restore(input);
    case 'publisher.status':return workspace.publisherState();
    case 'publisher.export':return workspace.publisherExport(input.kind,input.id);
    default:
      if(typeof action==='string'&&action.startsWith('publisher.'))return workspace.publisherAction(action,input);
      throw error('ACTION_UNKNOWN','Choose an available Grants.gov workspace action.',404);
  }
}

async function readJSON(request,maximum) {
  if(!/^application\/json(?:;|$)/i.test(request.headers['content-type']??''))
    throw error('JSON_REQUIRED','Use an application/json request.',415);
  const claimed=request.headers['content-length'];
  if(claimed!==undefined&&(!/^\d+$/.test(claimed)||Number(claimed)>maximum))
    throw error('REQUEST_TOO_LARGE','The request exceeds this host’s configured size.',413);
  const parts=[];let length=0;
  for await(const part of request) {
    length+=part.length;
    if(length>maximum)throw error('REQUEST_TOO_LARGE','The request exceeds this host’s configured size.',413);
    parts.push(part);
  }
  try {
    const input=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(Buffer.concat(parts)));
    if(!object(input))throw Error('object');
    return input;
  } catch {throw error('JSON_INVALID','Send one complete JSON object.');}
}

/** Binds only 127.0.0.1. A random token is delivered once in the URL fragment,
 * removed from the address bar by the page, and sent in Authorization headers.
 * All source and receiving files enter as complete packets or host CLI paths. */
export async function startGrantsServer({directory,workspace,port=0,token,
  buyerWorkspaces=[],transport,maxRequestBytes=256*1024*1024}={}) {
  if(!Number.isInteger(port)||port<0||port>65535)throw error('PORT_INVALID','Use a port from 0 to 65535.');
  if(!Number.isSafeInteger(maxRequestBytes)||maxRequestBytes<1024||maxRequestBytes>1024*1024*1024)
    throw error('REQUEST_LIMIT_INVALID','Configure a request limit from 1 KiB to 1 GiB.');
  token??=randomBytes(32).toString('base64url');
  if(typeof token!=='string'||!/^[A-Za-z0-9_-]{32,256}$/.test(token))
    throw error('SESSION_TOKEN_INVALID','Configure a random local session token.');
  const expected=Buffer.from('Bearer '+token),instanceId=randomUUID();
  const ownsWorkspace=!workspace;
  workspace??=await openGrantsWorkspace({directory,transport,buyerWorkspaces});
  const assets=new Map();
  try{for(const [path,[file,type]]of Object.entries(STATIC))
    assets.set(path,{data:await readFile(new URL(file,import.meta.url)),type});}
  catch(failure){if(ownsWorkspace)await workspace.close();throw failure;}
  let origin,closePromise,closing=false;
  const respond=(response,status,value,type='application/json; charset=utf-8',headers={})=>{
    const content=Buffer.isBuffer(value)?value:jsonBytes(value);
    response.writeHead(status,{
      'Content-Type':type,'Content-Length':String(content.length),
      'Cache-Control':'no-store','X-Content-Type-Options':'nosniff',
      'Referrer-Policy':'no-referrer','Cross-Origin-Resource-Policy':'same-origin',
      'Content-Security-Policy':"default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; form-action 'self'; frame-ancestors 'none'",
      ...headers
    });response.end(content);
  };
  const authorize=request=>{
    const actual=Buffer.from(request.headers.authorization??'');
    if(actual.length!==expected.length||!timingSafeEqual(actual,expected))
      throw error('SESSION_REQUIRED','Open the current local workspace link.',401);
    if(request.headers.origin!==undefined&&request.headers.origin!==origin)
      throw error('ORIGIN_MISMATCH','Use the original local workspace page.',403);
    if(request.headers['sec-fetch-site']==='cross-site')
      throw error('ORIGIN_MISMATCH','Use the original local workspace page.',403);
  };
  const server=createServer(async(request,response)=>{
    try{
