        id TEXT PRIMARY KEY, kind TEXT NOT NULL, revision INTEGER NOT NULL,
        state TEXT NOT NULL, request TEXT NOT NULL, request_sha256 TEXT NOT NULL,
        created_at TEXT NOT NULL, completed_at TEXT, result TEXT, error TEXT
      );
